import numpy as np
# manual centroids copied from detector recompute and fit
f=np.load('source_pixels.npz')['rgb']; xs=[];ys=[]
for im in f:
 r,g,b=[im[:,:,j].astype(int) for j in range(3)]
 m=(g>75)&(g>r*1.05)&(r>45)&(b<90)&(r+g-2*b>80)
 yy,xx=np.where(m)
 # select component around expected via all comps then max yellow compact (only one)
 seen=np.zeros(m.shape,bool);cs=[]
 for Y,X in zip(yy,xx):
  if seen[Y,X]:continue
  st=[(Y,X)];seen[Y,X]=1;p=[]
  while st:
   q=st.pop();p.append(q)
   for dy in(-1,0,1):
    for dx in(-1,0,1):
     a,c=q[0]+dy,q[1]+dx
     if 0<=a<144 and 0<=c<256 and m[a,c] and not seen[a,c]:seen[a,c]=1;st.append((a,c))
  if len(p)>=3:
   xa=np.array([z[1] for z in p]);ya=np.array([z[0] for z in p])
   if xa.ptp()<=10 and ya.ptp()<=10:cs.append((len(p),xa.mean(),ya.mean()))
 cs.sort(reverse=True); xs.append(cs[0][1]);ys.append(cs[0][2])
for end in [24,26,28]:
 t=np.arange(end+1)
 print(end,'xlin',np.polyfit(t,np.array(xs[:end+1]),1),'yquad',np.polyfit(t,np.array(ys[:end+1]),2))
# estimate true pixel sprite location using bounding box centers likely
